import{d as u,C as t,o as g,c,j as a,a as s,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第六十三章","description":"从为无为到难于细易，分辨报怨以德的王弼注法，理解不轻诺、不轻事。","frontmatter":{"title":"道德经第六十三章","description":"从为无为到难于细易，分辨报怨以德的王弼注法，理解不轻诺、不轻事。","category":"guide","aliases":["道德经第六十三章","老子第六十三章","dao de jing chapter 63"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-63.md","filePath":"daoism/dao-de-jing/chapter-63.md","lastUpdated":1794189804000}'),x={name:"daoism/dao-de-jing/chapter-63.md"},_=u({...x,setup(b){const r=[{id:"acting-without-forcing",label:"为无为，事无事，味无味",showLabel:!0,sentences:[["为",{text:"无为",glossary:"wuwei"},"，事",{text:"无事",glossary:"wushi"},"，味",{text:"无味",glossary:"wuwei-taste"},"。"]],note:["【白话】以不妄为的方式行事，以不妄造事端的方式处事，以恬淡无浓味为所体味。三句都在改变取向，而不是把生活与行动全部取消。","【王弼注择要】「以无为为居，以不言为教，以恬淡为味，治之极也。」注以无为、不言、恬淡贯通这一组句子。","【读法】味前字是体味、后字取滋味之象；无味在此依恬淡读，可与第三十五章道之出口淡乎其无味相参。"]},{id:"small-large-and-responding-to-resentment",label:"大小多少，报怨以德",showLabel:!0,sentences:[["大小多少，",{text:"报怨",glossary:"baoyuan"},"以",{text:"德",glossary:"de"},"。"]],note:["【白话】按句面的一种读法：把小的事情看重，把少的事情认真对待，以德回应怨恨。大小多少语义简约，后接王注另有小怨、大怨的区分。","【王弼注择要】「小怨则不足以报，大怨则天下之所欲诛。」注继而说「顺天下之所同者，德也」，以不私报小怨、顺公共同欲处置大怨解释德。","【读法】诛在此有责罚、诛讨之意，保留古注的政治处置语境；不把它改成王弼主张以恩惠回报一切伤害，也不把这段古注直接变成今日私人惩罚的授权。"]},{id:"planning-while-easy-and-small",label:"图难于其易，为大于其细",showLabel:!0,sentences:[[{text:"图",glossary:"tu"},{text:"难",glossary:"nan"},"于其",{text:"易",glossary:"yi"},"，为大于其",{text:"细",glossary:"xi"},"。天下",{text:"难",glossary:"nan"},"事，必",{text:"作",glossary:"zuo"},"于",{text:"易",glossary:"yi"},"；天下大事，必",{text:"作",glossary:"zuo"},"于",{text:"细",glossary:"xi"},"。"]],note:["【白话】筹划难事，要在它还容易时着手；成就大事，要从它还细小时做起。天下的难事都从容易处开始，大事都从细小处生发。","【读法】这几句在所据录文未见独立逐句注，可与末段王弼难于细易的解释相接。图为谋划，作为开始、生发；易与细写尚可从容处理的阶段。","【读法】这是一种由小察大的做事原则。用于具体事务时，还须分辨哪些小事确会积累成患，哪些只是可以容纳的正常差异。"]},{id:"not-seeking-the-grand",label:"圣人终不为大",showLabel:!0,sentences:[["是以圣人终不为大，故能成其大。"]],note:["【白话】因此圣人始终不以强做大事、追逐大名为目标，反而能够成就其大。它承接上文从细易着手的次序。","【读法】所据本句未见单独王注，本站按上下文解释不为大：不越过细微条件，直接追求显大的结果；不将它理解为只能做小事。","【读法】大是否能成，还要看实际条件与持续行动。不为大不是一句保证成功的技巧，而是对强求规模与名目的反省。"]},{id:"promises-and-taking-things-lightly",label:"夫轻诺必寡信，多易必多难",showLabel:!0,sentences:[["夫",{text:"轻诺",glossary:"qingnuo"},"必",{text:"寡信",glossary:"guaxin"},"，多",{text:"易",glossary:"yi-light"},"必多",{text:"难",glossary:"nan"},"。"]],note:["【白话】轻率许诺，便容易少有兑现的信用；把许多事情都看得太容易，反而会遇到更多困难。轻诺与多易，都忽略了承担所需的条件。","【读法】本句在所据录文未见单独逐句注；它把前面的难易关系转到行动者的态度。诺为应允，寡信联系能否履约；易在多易中作轻视、看轻。","【读法】这也提醒人区分真有把握与随口保证。把范围、条件和未知说清，往往比立即答应更能维持信任。"]},{id:"taking-difficulty-seriously",label:"是以圣人犹难之",showLabel:!0,sentences:[["是以圣人犹",{text:"难",glossary:"nan-treat"},"之，故终无",{text:"难",glossary:"nan"},"矣。"]],note:["【白话】因此连圣人也仍把事情看作有难处，审慎对待，所以最终不至陷入难以收拾的困局。承上读，慎重发生在细小、容易的时候。","【王弼注择要】「以圣人之才，犹尚难于细易。」注反问没有圣人之才的人何以「欲忽于此乎」，突出不忽细易。","【读法】所据经文在犹难之前另见曰字，本站保留现文不增。终无难写章内慎重以免患的理想结果，不表示谨慎的人永远不会遇到外在困难。"]}],o=[{id:"wuwei",term:"无为",sense:1},{id:"wushi",term:"无事",sense:1},{id:"wuwei-taste",term:"无味",sense:1},{id:"baoyuan",term:"报怨",sense:1},{id:"de",term:"德",sense:6},{id:"tu",term:"图",sense:1},{id:"yi",term:"易",sense:1},{id:"yi-light",term:"易",sense:2},{id:"xi",term:"细",sense:1},{id:"zuo",term:"作",sense:1},{id:"qingnuo",term:"轻诺",sense:1},{id:"guaxin",term:"寡信",sense:1},{id:"nan",term:"难",sense:1},{id:"nan-treat",term:"难",sense:2}];return(p,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十三章",tabindex:"-1"},[s("道德经第六十三章 "),a("a",{class:"header-anchor",href:"#道德经第六十三章","aria-label":'Permalink to "道德经第六十三章"'},"​")],-1)),n(i,{title:"不争着做大事，为什么反能成其大",summary:"本章以无为、无事、无味起笔，转入大小多少与报怨，再把做事的着力处放在尚易、尚细的时候，最后警戒轻诺与轻易。王弼对报怨区分小怨、大怨，所说德并非一概以好处回赠伤害。",points:[{label:"先读",text:"为无为、事无事仍在说如何行动，味无味则以恬淡为取向。"},{label:"再辨",text:"大小多少与报怨以德先释句面，再列王注小怨不报、大怨顺天下所同的取径。"},{label:"后看",text:"图难于易、为大于细与犹难之相接，重在早作、慎作，也不轻许承诺。"}],hint:"图为谋划；轻诺的诺读 nuò，寡信的寡读 guǎ。易既可说尚易的阶段，也可作轻视、看得太容易，分别标义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:r,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"大小多少，报怨以德。",tone:"句面与王注分列",guide:"王弼区分小怨、大怨，再以顺天下之所同释德。"},{text:"图难于其易，为大于其细。",tone:"把着力处前移",guide:"看见事情形成的阶段，不只追逐显著的规模和结果。"},{text:"夫轻诺必寡信，多易必多难。",tone:"不把容易当成轻率",guide:"对细易认真，才有条件承担许诺，避免临末陷困。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:o}),e[4]||(e[4]=m("",15))])}}});export{f as __pageData,_ as default};
